private int advanceWatermark(SessionKey key, int watermark) {
    List<Integer> pending = sessionRepository.findPendingSeqs(key.deviceId(), key.sessionId(), watermark);
    int current = watermark;
    for (int seq : pending) {
        if (seq == current + 1) current = seq;
        else break;
    }
    return current;
}
