                .isEqualTo(2);

        // 已成功旧键仍重放首次响应（当时未关闭），而非当前状态
        uploadBatch("req-k1", List.of(
                message("dev-10", "s-1", 1, createCommand("o-k1", "obs-k1", "站点A", "1.0", "一")),
