 */
@SpringBootTest
class DeviceSessionConcurrencyTest {

    @Autowired
    private DeviceSessionService deviceSessionService;

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @BeforeEach
    void cleanDatabase() {
        jdbcTemplate.update("DELETE FROM session_receipt");
